/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_gemver[[gnu::flatten, gnu::noinline]](int n,
		   DATA_TYPE alpha,
		   DATA_TYPE beta,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(u1,N,n),
		   DATA_TYPE POLYBENCH_1D(v1,N,n),
		   DATA_TYPE POLYBENCH_1D(u2,N,n),
		   DATA_TYPE POLYBENCH_1D(v2,N,n),
		   DATA_TYPE POLYBENCH_1D(w,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n),
		   DATA_TYPE POLYBENCH_1D(z,N,n))
{
  int i, j;

  /* Temporary vector used to hold alpha * x[j].
     This removes one multiplication from the O(N^2) w-update loop and
     lets that loop be a plain matrix-vector product. */
  DATA_TYPE x_alpha[_PB_N];

#pragma scop

  /* --------------------------------------------------------------------
   * Phase 1: Fused rank-2 update of A and accumulation into x
   *
   * Original code (two separate loops):
   *
   *   // 1) A := A + u1 v1^T + u2 v2^T
   *   for i
   *     for j
   *       A[i][j] = A[i][j] + u1[i] * v1[j] + u2[i] * v2[j];
   *
   *   // 2) x := x + beta * A^T y
   *   for i
   *     for j
   *       x[i] = x[i] + beta * A[j][i] * y[j];
   *
   * After the initialization, x is zero, but in general x may hold
   * an incoming value; both are preserved here.
   *
   * We fuse these two loops and traverse A by rows (i = row index,
   * j = column index), which improves spatial locality (row-major).
   *
   * For each row i, we:
   *   - compute the updated A[i][j] (rank-2 update),
   *   - immediately use that updated A[i][j] to accumulate the
   *     contribution beta * A[i][j] * y[i] into x[j].
   *
   * Algebraically this computes:
   *   A[i][j] <- A[i][j] + u1[i] v1[j] + u2[i] v2[j]   (rank-2 update)
   *   x[j]    <- x[j] + beta * sum_i A[i][j] y[i]      (A^T y product)
   *
   * which is exactly the original computation, just reordered.
   * ------------------------------------------------------------------ */
  for (i = 0; i < _PB_N; i++)
  {
    /* Row-invariant values kept in registers. */
    DATA_TYPE u1_i      = u1[i];
    DATA_TYPE u2_i      = u2[i];
    DATA_TYPE beta_y_i  = beta * y[i];
    DATA_TYPE *Ai       = A[i];  /* Pointer to row i of A for faster access. */

    for (j = 0; j < _PB_N; j++)
    {
      /* Updated matrix entry: A[i][j] + u1[i]*v1[j] + u2[i]*v2[j]. */
      DATA_TYPE a_ij = Ai[j] + u1_i * v1[j] + u2_i * v2[j];
      Ai[j] = a_ij;

      /* Accumulate contribution of this updated A[i][j] to x[j]:
         x[j] += beta * y[i] * A[i][j]. */
      x[j] += beta_y_i * a_ij;
    }
  }

  /* --------------------------------------------------------------------
   * Phase 2: x := x + z
   *
   * Original third loop:
   *   for i
   *     x[i] = x[i] + z[i];
   *
   * This is kept as a simple, contiguous vector operation.
   * ------------------------------------------------------------------ */
  for (i = 0; i < _PB_N; i++)
    x[i] += z[i];

  /* --------------------------------------------------------------------
   * Phase 3: Pre-scale x by alpha once:
   *
   *   x_alpha[j] = alpha * x[j]
   *
   * so that the final matrix-vector product can be written as:
   *
   *   w[i] += A[i][j] * x_alpha[j]
   *
   * instead of:
   *
   *   w[i] += alpha * A[i][j] * x[j]
   *
   * This removes one multiplication per A[i][j] from the O(N^2) loop.
   * ------------------------------------------------------------------ */
  for (j = 0; j < _PB_N; j++)
    x_alpha[j] = alpha * x[j];

  /* --------------------------------------------------------------------
   * Phase 4: w := w + alpha * A * x
   *          implemented as w := w + A * x_alpha
   *
   * Original code:
   *   for i
   *     for j
   *       w[i] = w[i] + alpha * A[i][j] * x[j];
   *
   * After introducing x_alpha, we have:
   *   w[i] = w[i] + sum_j A[i][j] * x_alpha[j]
   *
   * which is mathematically identical to the original expression:
   *   w[i] = w[i] + alpha * sum_j A[i][j] * x[j]
   *
   * Access to A is row-major and contiguous in j, which is friendly
   * to caches and SIMD. We accumulate into a local scalar "wi" to
   * reduce memory traffic on w[i].
   * ------------------------------------------------------------------ */
  for (i = 0; i < _PB_N; i++)
  {
    DATA_TYPE *Ai = A[i];  /* Row i of A. */
    DATA_TYPE wi  = w[i];

    for (j = 0; j < _PB_N; j++)
      wi += Ai[j] * x_alpha[j];

    w[i] = wi;
  }

#pragma endscop
}


int main(int argc, char** argv)
