     - x_alpha[j] = alpha * x[j] (hoist alpha out of N^2 loop)
     Their size is O(N), negligible compared to the N×N matrix A. */
  DATA_TYPE y_beta[n];
  DATA_TYPE x_alpha[n];

  /* Square tiling factor for the matrix loops.
     64×64 tiles of doubles fit nicely in L1/L2 on modern x86_64. */
  const int T = 64;

#pragma scop

  /* ------------------------------------------------------------------
   * 1) Rank-2 update:
   *      A := A + u1 * v1^T + u2 * v2^T
   *
   *    Original:
   *      for i
   *        for j
   *          A[i][j] += u1[i]*v1[j] + u2[i]*v2[j];
   *
   *    Optimization:
   *      - 2D tiling over (i, j) to improve cache locality in A and v1/v2.
   *      - Hoist u1[i] and u2[i] out of the inner j-loop.
   * ------------------------------------------------------------------ */
  for (int ii = 0; ii < _PB_N; ii += T) {
    int i_end = ii + T;
    if (i_end > _PB_N)
      i_end = _PB_N;

    for (int jj = 0; jj < _PB_N; jj += T) {
      int j_end = jj + T;
      if (j_end > _PB_N)
        j_end = _PB_N;

      for (i = ii; i < i_end; ++i) {
        DATA_TYPE u1_i = u1[i];
        DATA_TYPE u2_i = u2[i];

        for (j = jj; j < j_end; ++j) {
          A[i][j] = A[i][j]
                    + u1_i * v1[j]
                    + u2_i * v2[j];
        }
      }
    }
  }

  /* ------------------------------------------------------------------
   * 2) Precompute y_beta[j] = beta * y[j]
   *    This removes one multiplication by beta from the N×N x-update.
   * ------------------------------------------------------------------ */
  for (j = 0; j < _PB_N; ++j) {
    y_beta[j] = beta * y[j];
  }

  /* ------------------------------------------------------------------
   * 3) x <- x + A^T * (beta * y)
   *
   *    Original code:
   *      for (i)
   *        for (j)
   *          x[i] += beta * A[j][i] * y[j];
   *
   *    We rewrite in a cache-friendly form using y_beta:
   *      for (j)                    // iterate over rows of A
   *        for (i)
   *          x[i] += A[j][i] * y_beta[j];
   *
   *    This is mathematically equivalent:
   *      x[i] = x[i] + sum_j A[j,i] * (beta*y[j]).
   *    With A stored row-major, A[j][i] is traversed with unit stride
   *    in the inner i-loop (contiguous access to each row A[j,*]).
   * ------------------------------------------------------------------ */
  for (j = 0; j < _PB_N; ++j) {
    DATA_TYPE yb = y_beta[j];
    DATA_TYPE *A_row = A[j];

    for (i = 0; i < _PB_N; ++i) {
      x[i] += A_row[i] * yb;
    }
  }

  /* ------------------------------------------------------------------
   * 4) x <- x + z
   *
   *    Original:
   *      for (i) x[i] += z[i];
   *
   *    This is kept as a separate simple, vectorizable loop.
   * ------------------------------------------------------------------ */
  for (i = 0; i < _PB_N; ++i) {
    x[i] += z[i];
  }

  /* ------------------------------------------------------------------
   * 5) Precompute x_alpha[j] = alpha * x[j]
   *
   *    This hoists alpha out of the N×N loop for w, reducing the number
   *    of multiplications by alpha from O(N^2) to O(N).
   * ------------------------------------------------------------------ */
  for (j = 0; j < _PB_N; ++j) {
    x_alpha[j] = alpha * x[j];
  }

  /* ------------------------------------------------------------------
   * 6) w <- w + A * x_alpha
   *
   *    Original:
   *      for (i)
   *        for (j)
   *          w[i] += alpha * A[i][j] * x[j];
   *
   *    Using x_alpha:
   *      for (i)
   *        for (j)
   *          w[i] += A[i][j] * x_alpha[j];
   *
   *    Optimization:
   *      - 1D tiling over the row dimension i to improve cache reuse of
   *        A's rows and write-combining on w.
   *      - Accumulate into a local scalar wi to reduce memory traffic.
   * ------------------------------------------------------------------ */
  for (int ii = 0; ii < _PB_N; ii += T) {
    int i_end = ii + T;
    if (i_end > _PB_N)
      i_end = _PB_N;

    for (i = ii; i < i_end; ++i) {
      DATA_TYPE *A_row = A[i];
      DATA_TYPE wi = w[i];

      for (j = 0; j < _PB_N; ++j) {
        wi += A_row[j] * x_alpha[j];
      }

      w[i] = wi;
    }
  }

#pragma endscop
}


