   *   for (i)
   *     for (j)
   *       A[i][j] += u1[i]*v1[j] + u2[i]*v2[j];
   *
   *   for (i)
   *     for (j)
   *       x[i] += beta * A[j][i] * y[j];
   *
   * Reordered and fused (row-major traversal):
   *   for (j)                     // row index of A
   *     for (i)                   // column index of A
   *       A[j][i] += ...
   *       x[i]    += beta * y[j] * A[j][i];
   *
   * For each element (j, i), A[j][i] is updated exactly once with
   * the same formula, and then the updated value is used to
   * accumulate beta * A[j][i] * y[j] into x[i].  The order of
   * contributions to each x[i] over j is preserved (j = 0..N-1),
   * so the result matches the original up to floating-point
   * roundoff.
   * ------------------------------------------------------------- */
  for (j = 0; j < N; ++j)
  {
    const DATA_TYPE u1j = u1_[j];
    const DATA_TYPE u2j = u2_[j];
    const DATA_TYPE beta_yj = beta * y_[j];

    /* Tile over i (columns) for better cache locality on A[j][i]
       and x[i]. */
    for (int ii = 0; ii < N; ii += TILE_I)
    {
      const int i_end = (ii + TILE_I < N) ? (ii + TILE_I) : N;
      for (i = ii; i < i_end; ++i)
      {
        /* Rank-2 update on A's row j, column i. */
        DATA_TYPE a = A_[j][i] + u1j * v1_[i] + u2j * v2_[i];
        A_[j][i] = a;

        /* Accumulate contribution from row j into x[i]. */
        x_[i] += beta_yj * a;
      }
    }
  }

  /* Add z to x:
       x[i] = x[i] + z[i];
     This completes the original x-update. */
  for (i = 0; i < N; ++i)
  {
    x_[i] += z_[i];
  }

  /* Precompute alpha * x[j] in a separate vector.  This removes
     the multiplication by alpha from the inner loop of the final
     GEMV, reducing the total number of multiplications from
     O(N^2) to O(N) for that factor. */
  for (i = 0; i < N; ++i)
  {
    x_scaled[i] = alpha * x_[i];
  }

  /* -------------------------------------------------------------
   * Final GEMV:
   *
   * Original:
   *   for (i)
   *     for (j)
   *       w[i] += alpha * A[i][j] * x[j];
   *
   * With x_scaled[j] = alpha * x[j], we compute:
   *   w[i] += A[i][j] * x_scaled[j];
   *
   * which is mathematically identical:
   *   A[i][j] * x_scaled[j] = alpha * A[i][j] * x[j].
   *
   * We traverse A row-major (i outer, j inner), which is its
   * natural layout, and tile over j to improve cache reuse of
   * x_scaled[j] and of A's rows.
   * ------------------------------------------------------------- */
  for (i = 0; i < N; ++i)
  {
    DATA_TYPE wi = w_[i];

    for (int jj = 0; jj < N; jj += TILE_J)
    {
      const int j_end = (jj + TILE_J < N) ? (jj + TILE_J) : N;
      for (j = jj; j < j_end; ++j)
      {
        wi += A_[i][j] * x_scaled[j];
      }
    }

    w_[i] = wi;
  }

#pragma endscop
}


